package com.example.tango

import kotlinx.serialization.Serializable

// 1. 単語データのモデル
@Serializable
data class Word(
    val id: Int,
    val english: String,
    val japanese: String,
    val category: String = "一般",
    val fileName: String = "デフォルト"
)

// 全データのバックアップ用モデル
@Serializable
data class AppBackup(
    val categoryFiles: Map<String, List<String>>,
    val wordList: List<Word>,
    val wrongCounts: Map<String, Int>,
    val correctCounts: Map<String, Int>,
    val lastWrongTimes: Map<String, Long>,
    val weeklyHistory: Map<String, Int>,
    val currentStreak: Int,
    val todayDate: String,
    val todayTotal: Int,
    val todayCorrect: Int
)

// テスト中の履歴（巻き戻し用）
data class TestHistory(
    val index: Int,
    val score: Int,
    val word: Word,
    val wasCorrect: Boolean
)
